contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, address key) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "not enough balance");

        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint stored = c.balances(key); if (__ESBMC_reverted()) return;

        assert(stored == c.balances(key));
    }

    receive() external payable {}
}

