// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 amount, address key) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 stored;
        try c.balances(key) returns (uint256 __r) { stored = __r; } catch { return; }
        assertTrue(stored == c.balances(key));
    }

    function testFuzz_run(uint256 amount, address key) public {
        vm.assume(key.code.length == 0 && uint160(key) > 0xffff && key != address(this) && key != address(c) && key != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && key != 0x000000000000000000636F6e736F6c652e6c6f67 && key != 0x4e59b44847b379578588920cA78FbF26c0B4956C && key != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(amount, key);
    }

    receive() external payable {}
}
